190→			expect.soft(snapshot(await store.readSettlementPlan(PROGRESS_SCOPE))).toEqual(before);
			expect.soft(await store.readLineage(PROGRESS_SCOPE)).toEqual({ exhausted: false, next: 0 });
		});
	});
